# Mã nguồn cho bài Kiểm tra số nguyên tố
import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

n = int(input())
print("YES" if is_prime(n) else "NO")

